 const target=cleanText(input.target,1000),visible=caseTargetIds(target,process.env.PUBLIC_URL||req.url);try{const address=new URL(target,process.env.PUBLIC_URL||req.url),base=new URL(process.env.PUBLIC_URL||req.url);if(address.origin===base.origin){const match=address.pathname.match(/^\/(docs|skills|resources)\/shared\/([a-f0-9-]{36})$/),entry=match?getCatalogTarget(match[2],match[1]):null;if(entry?.community_post)visible.post=entry.community_post;}}catch{};let targetId=cleanText(input.post,80),commentId=cleanText(input.comment,80);
 if(target&&targetId)requireValue(targetId===visible.post,'目标地址与分享编号不一致');
 if(target&&commentId)requireValue(commentId===visible.comment,'目标地址与评论编号不一致');
 targetId=targetId||visible.post||'';commentId=commentId||visible.comment||'';
 const reportedComment=commentId?db().prepare('SELECT * FROM community_comments WHERE id=?').get(commentId):null;if(commentId){requireValue(reportedComment,'目标评论暂不可用',404);requireValue(!targetId||targetId===reportedComment.post,'评论与分享不匹配',404);targetId=reportedComment.post;}
 const row=targetId?getPost(targetId):null;requireValue(!targetId||row,'目标分享暂不可用',404);requireValue(row||target||kind==='appeal','请填写可定位的内容地址或账号问题');if(kind==='appeal'){requireValue(user,'请先登录后提交申诉',401);requireValue(reportedComment?reportedComment.author===user.id:(!row||row.author===user.id),'仅可对自己的内容或账号提出申诉',403)}else if(row)requireValue(row.visibility==='public'||isStaff(user)||(user&&row.author===user.id),'内容暂不可用',404);
